import os, sys, json, types, importlib.util, tempfile

# Build fake segment objects mimicking the SDK's pydantic models (attribute access)
class Seg:
    def __init__(self, category, pages, confidence_category):
        self.category = category
        self.pages = pages
        self.confidence_category = confidence_category

class Result:
    def __init__(self, segments):
        self.segments = segments

class GetResp:
    def __init__(self, segments, status="completed", error_message=None):
        self.result = Result(segments)
        self.status = status
        self.error_message = error_message

class FakeFileResp:
    def __init__(self, id_):
        self.id = id_

class FakeFiles:
    def create(self, *, file, purpose, **kw):
        assert purpose == "split", purpose
        return FakeFileResp("fake-file-id-123")

class FakeSplit:
    def split(self, *, categories, document_input, **kw):
        assert document_input == {"type": "file_id", "value": "fake-file-id-123"}, document_input
        assert isinstance(categories, list) and categories
        segs = [
            Seg("essay", [1, 2, 3], "high"),
            Seg("research_paper", [4, 5, 6, 7, 8], "high"),
        ]
        return GetResp(segs)

